/**
 * Workspace dashboard — an AI-first home, not a metrics console.
 *
 * The page is one argument in three parts, and the order is the
 * argument: what you can do (hero, composer, starters), what you were
 * doing (the resume pill, recent conversations), and only then what it
 * costs (plan state). An earlier version led with five stat tiles and
 * five settings links, which reads as an admin console for a product
 * the person hasn't used yet.
 *
 * The layout: the hero and the composer are one unit, centred in the
 * viewport, and everything secondary is one quiet strip at the foot.
 * Before this, the hero sat at the top and the composer was pinned to
 * the bottom with a page of nothing between them, and the secondary
 * material was three separate sections at three different widths.
 * Everything now shares one measure.
 *
 * Everything configurable lives in two consumer-owned seams:
 * `@/lib/dashboard-config` (hero copy, starters, chat base path) and
 * `@/lib/dashboard-data` (`getResume` — what "unfinished work" means
 * for this product). Neither requires editing a file this item ships.
 *
 * Pairs with the `chat` item: the composer and the starters open
 * `${chatBasePath}/<new-uuid>?query=…`, which the chat panel sends as
 * the first turn. Without a chat surface installed, set `chatBasePath`
 * or drop those affordances.
 *
 * Workspace resolution: `requireWorkspace()` is called directly and
 * allowed to throw. The `app-shell` item's layout already guarantees an
 * active workspace before any `(app)` route renders, so a failure here
 * means something is genuinely wrong (a revoked session mid-request),
 * not an empty state — and this item ships an `error.tsx` for exactly
 * that.
 *
 * No `actions.ts`: every read is a plain server-side call with no
 * client-triggered refetch (contrast the `usage` item, whose period
 * selector needs one).
 */

import type { Metadata } from "next";
import { getTimeZone, getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import { getTrialStatus, getWorkspaceBilling } from "@intelligo-dev/billing";
import { listConversations } from "@intelligo-dev/core/conversations";
import { summarizeExecutions } from "@intelligo-dev/executions";

import { DashboardHero } from "@/components/dashboard/dashboard-hero";
import { PlanSummary } from "@/components/dashboard/plan-summary";
import { PromptBar } from "@/components/dashboard/prompt-bar";
import { RecentConversations } from "@/components/dashboard/recent-conversations";
import { dashboardConfig } from "@/lib/dashboard-config";
import { getResume } from "@/lib/dashboard-data";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("dashboard");
  return { title: t("meta.title") };
}

/**
 * The first moment of this month where the reader is sitting.
 *
 * The server's own zone is nobody's: it used to decide when "this
 * month" began, so the figure here and the one on the usage page could
 * disagree for a day at every month boundary. next-intl already
 * resolves the reader's zone for formatting; this uses the same one.
 */
async function startOfMonth(): Promise<Date> {
  const timeZone = await getTimeZone();

  /** How far the zone is from UTC at this instant, in milliseconds. */
  const offsetMs = (date: Date) => {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour12: false,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    }).formatToParts(date);
    const value = (type: string) =>
      Number(parts.find((part) => part.type === type)?.value ?? "0");
    // The wall clock there, read as if it were UTC, minus the instant.
    return (
      Date.UTC(
        value("year"),
        value("month") - 1,
        value("day"),
        value("hour") % 24,
        value("minute"),
        value("second")
      ) - date.getTime()
    );
  };

  const now = new Date();
  const here = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
  }).formatToParts(now);
  const value = (type: string) =>
    Number(here.find((part) => part.type === type)?.value ?? "0");

  // Midnight on the first, corrected by the offset — twice, because the
  // first correction can land the other side of a DST change.
  const naive = Date.UTC(value("year"), value("month") - 1, 1);
  const guess = naive - offsetMs(new Date(naive));
  return new Date(naive - offsetMs(new Date(guess)));
}

export default async function DashboardPage() {
  const t = await getTranslations("dashboard");
  const { workspace, user } = await requireWorkspace();
  const actor = { workspaceId: workspace.id, userId: user.id };

  const [recent, resume, monthSummary, billing, trial] = await Promise.all([
    listConversations(actor, { limit: 5 }),
    getResume(actor, { chatBasePath: dashboardConfig.chatBasePath }),
    summarizeExecutions(workspace.id, {
      from: await startOfMonth(),
      to: new Date(),
    }),
    getWorkspaceBilling(workspace.id),
    getTrialStatus(workspace.id),
  ]);

  const showPlan = dashboardConfig.showPlanSummary !== false;

  return (
    <div className="flex min-h-full flex-col px-4">
      {/* The hero and the composer are one unit, centred in whatever the
          viewport leaves: a question and the box that answers it should
          not be a page apart. */}
      <div className="flex flex-1 flex-col justify-center py-10">
        <div className="mx-auto w-full max-w-3xl">
          <DashboardHero resume={resume} />
          <PromptBar />
        </div>
      </div>

      {/* One quiet strip, not three sections: what you were doing on the
          left, what it costs on the right, both at the page's measure. */}
      <div className="mx-auto w-full max-w-3xl">
        <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2 border-t py-4">
          <RecentConversations
            conversations={recent.map((conversation) => ({
              id: conversation.id,
              title: conversation.title,
              updatedAt: conversation.updatedAt.toISOString(),
            }))}
          />

          {showPlan ? (
            <PlanSummary
              planName={billing.plan?.name ?? t("plan.freeName")}
              charged={monthSummary.totals.charged[0] ?? null}
              requestsThisMonth={monthSummary.totals.count}
              trial={{
                hasTrialCredits: trial.hasTrialCredits,
                status: trial.status,
                creditsRemaining: trial.creditsRemaining,
                initialCredits: trial.initialCredits,
                percentageRemaining: trial.percentageRemaining,
                daysRemaining: trial.daysRemaining,
              }}
            />
          ) : null}
        </div>
      </div>
    </div>
  );
}

{
  "meta": {
    "title": "Dashboard"
  },
  "hero": {
    "title": "What can I help with?",
    "subtitle": "Ask a question, draft something, or pick up where you left off. Every turn is metered against your plan.",
    "resume": "Continue where you left off"
  },
  "starters": {
    "first": "Explain what this workspace can do",
    "second": "Draft a short update for my team",
    "third": "Summarize the key points of an idea"
  },
  "promptBar": {
    "placeholder": "Ask anything…",
    "send": "Send",
    "voiceStart": "Start voice input",
    "voiceStop": "Stop voice input"
  },
  "recent": {
    "title": "Recent",
    "untitled": "New conversation"
  },
  "plan": {
    "title": "Plan & usage",
    "freeName": "Free",
    "requests": "{count, plural, =0 {No requests this month} one {# request this month} other {# requests this month}}",
    "trialRemaining": "{remaining} of {initial} trial credits left",
    "trialDays": "{days, plural, one {# day left} other {# days left}}",
    "viewUsage": "View usage",
    "viewPlans": "View plans"
  }
}

"use client";

/**
 * Error boundary for the workspace dashboard. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="dashboard" />;
}

"use client";

/**
 * What this workspace is for, and a way back into unfinished work.
 *
 * Deliberately short: the hero's job is to name the surface and then
 * get out of the way of the composer directly beneath it. Starters
 * belong to the composer (`prompt-bar.tsx`), because they are ways of
 * filling it rather than a separate menu of features — keeping them
 * here put three cards between the question and the box that answers
 * it.
 *
 * Not a stat wall: plan, spend and token counts are real but secondary,
 * and they live in the strip at the foot of the page. A person opening
 * the app wants to do the thing, not read a meter.
 */

import { ArrowRight, Sparkles } from "lucide-react";
import { useTranslations } from "next-intl";

import { useRouter } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";
import type { ResumeTarget } from "@/lib/dashboard-data";

interface DashboardHeroProps {
  resume: ResumeTarget | null;
}

export function DashboardHero({ resume }: DashboardHeroProps) {
  const t = useTranslations("dashboard");
  // Namespace-less: hero keys are fully qualified so a product can
  // point them at its own namespace (see `@/lib/dashboard-config`).
  const tAny = useTranslations();
  const router = useRouter();

  const Icon = dashboardConfig.hero?.icon ?? Sparkles;

  const title = dashboardConfig.hero?.titleKey
    ? tAny(dashboardConfig.hero.titleKey)
    : t("hero.title");
  const subtitle = dashboardConfig.hero?.subtitleKey
    ? tAny(dashboardConfig.hero.subtitleKey)
    : t("hero.subtitle");

  return (
    <div className="text-center">
      <div className="flex justify-center">
        <div className="flex size-12 items-center justify-center rounded-full bg-primary/10">
          <Icon className="size-6 text-primary" strokeWidth={1.75} />
        </div>
      </div>

      <h1 className="mt-5 text-3xl font-semibold tracking-tight md:text-4xl">
        {title}
      </h1>
      <p className="mx-auto mt-3 max-w-xl text-base text-muted-foreground">
        {subtitle}
      </p>

      {resume ? (
        <button
          type="button"
          onClick={() => router.push(resume.href)}
          // `max-w-full` and a truncating label: a resumed conversation
          // is titled from its first message, which on a phone is wider
          // than the screen and wrapped the pill into a block.
          className="mt-5 inline-flex max-w-full items-center gap-1.5 rounded-full bg-accent/60 px-3.5 py-1.5 text-xs font-medium transition-colors hover:bg-accent"
        >
          <span
            className="size-1.5 shrink-0 rounded-full bg-primary"
            aria-hidden
          />
          <span className="truncate">{resume.label ?? t("hero.resume")}</span>
          <ArrowRight className="size-3.5 shrink-0" />
        </button>
      ) : null}
    </div>
  );
}

"use client";

/**
 * The composer, and the ways of filling it.
 *
 * It sits directly under the hero rather than pinned to the foot of the
 * page: the question and the box that answers it belong together, and
 * with the composer stuck to the bottom the eye had to cross an empty
 * page to get from one to the other.
 *
 * It composes the same primitives the `chat` item's composer does, so
 * the home page behaves like the surface it hands off to: Enter sends
 * and Shift+Enter breaks a line (IME-safe), the textarea grows with its
 * content, and dictation appends to the draft.
 *
 * Both affordances — the composer and the starter cards — mint a
 * client-side UUID and navigate to `${chatBasePath}/${id}?query=…`; the
 * chat panel sends that as the first turn. Nothing is written here, so
 * an abandoned prompt leaves no empty conversation behind.
 *
 * No attachments, deliberately: the handoff to the chat surface is a
 * URL, which carries text and nothing else, so a file picked here would
 * be dropped by the navigation that follows. Attachments belong to the
 * conversation, one navigation later.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import {
  PromptInput,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "@/components/ui/ai-prompt-input";
import { SpeechInput } from "@/components/ui/ai-speech-input";
import { useRouter } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";

export function PromptBar() {
  const t = useTranslations("dashboard");
  // Namespace-less: starter keys are fully qualified so a product can
  // point them at its own namespace (the `chatConfig.starters` contract).
  const tAny = useTranslations();
  const router = useRouter();
  const [message, setMessage] = useState("");

  const chatBasePath = dashboardConfig.chatBasePath ?? "/chat";
  const starters = (dashboardConfig.starters ?? []).map((key) => tAny(key));

  function start(prompt: string) {
    const id = crypto.randomUUID();
    router.push(`${chatBasePath}/${id}?query=${encodeURIComponent(prompt)}`);
  }

  return (
    <div className="mt-8">
      <PromptInput
        onSubmit={({ text }) => {
          const prompt = (text ?? "").trim();
          if (!prompt) return;
          start(prompt);
        }}
      >
        <PromptInputTextarea
          value={message}
          onChange={(event) => setMessage(event.target.value)}
          placeholder={t("promptBar.placeholder")}
          aria-label={t("promptBar.placeholder")}
        />
        <PromptInputFooter>
          <PromptInputTools>
            <SpeechInput
              startLabel={t("promptBar.voiceStart")}
              stopLabel={t("promptBar.voiceStop")}
              onTranscript={(spokenText, isFinal) => {
                if (!isFinal) return;
                const spoken = spokenText.trim();
                if (!spoken) return;
                setMessage((current) =>
                  current ? `${current.replace(/\s+$/, "")} ${spoken}` : spoken
                );
              }}
            />
          </PromptInputTools>
          <PromptInputSubmit
            status="ready"
            label={t("promptBar.send")}
            disabled={!message.trim()}
          />
        </PromptInputFooter>
      </PromptInput>

      {starters.length > 0 ? (
        // Chips, not cards: under the composer these are one more way to
        // fill it, and at card weight they competed with it for the eye.
        <div className="mt-3 flex flex-wrap justify-center gap-2">
          {starters.map((starter, index) => (
            <button
              key={index}
              type="button"
              onClick={() => start(starter)}
              className="max-w-full rounded-full border border-border/60 px-3.5 py-1.5 text-xs text-muted-foreground transition-colors hover:border-border hover:bg-accent/40 hover:text-foreground"
            >
              <span className="block truncate">{starter}</span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

"use client";

/**
 * The left half of the page's foot: a few conversations to walk back
 * into.
 *
 * Three, not five, and inline rather than a titled list of rows: the
 * sidebar already carries the full history, so a second full list on
 * the home page was the same information twice at twice the weight.
 * What earns its place here is the shortest possible way back into
 * recent work.
 *
 * Timestamps are gone for the same reason — the sidebar groups by day,
 * and a relative time next to every title made three links read as a
 * table. (The `usage` item's table is the right place for the
 * billing-shaped view of the same activity.)
 */

import { MessageSquare } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { dashboardConfig } from "@/lib/dashboard-config";

export interface RecentConversation {
  id: string;
  title: string | null;
  /** ISO string — server components can't hand a Date to a client one. */
  updatedAt: string;
}

/** How many of the recent conversations the strip shows. */
const SHOWN = 3;

export function RecentConversations({
  conversations,
}: {
  conversations: RecentConversation[];
}) {
  const t = useTranslations("dashboard");

  if (conversations.length === 0) return null;

  const chatBasePath = dashboardConfig.chatBasePath ?? "/chat";

  return (
    <div className="flex min-w-0 flex-wrap items-center gap-x-4 gap-y-1 text-xs">
      <span className="font-medium uppercase tracking-wide text-muted-foreground">
        {t("recent.title")}
      </span>
      {conversations.slice(0, SHOWN).map((conversation) => (
        <Link
          key={conversation.id}
          href={`${chatBasePath}/${conversation.id}`}
          className="inline-flex max-w-full items-center gap-1.5 text-muted-foreground transition-colors hover:text-foreground"
        >
          <MessageSquare className="size-3.5 shrink-0" strokeWidth={2} />
          <span className="truncate">
            {conversation.title ?? t("recent.untitled")}
          </span>
        </Link>
      ))}
    </div>
  );
}

/**
 * The right half of the page's foot: plan, this month's spend, and a
 * trial's remaining credits when one is running.
 *
 * One line of facts rather than a bordered card under a section
 * heading. Nothing here is an action a person came to the home page to
 * take, and at card weight it argued with the composer for attention;
 * as a line it stays readable and stops pretending to be the point.
 *
 * A server component: every number is already resolved by the page.
 *
 * Money arrives as an amount that names its own currency and is
 * rendered through `formatMoney` (`@/lib/format-money`, shipped by the
 * `pricing` item), not against a symbol this file chooses. Install
 * `pricing` alongside this item, or drop the charged figure and its
 * import.
 */

import { getFormatter, getTranslations } from "next-intl/server";

import { Link } from "@/i18n/navigation";
import { formatMoney, type MoneyLike } from "@/lib/format-money";

export interface PlanSummaryProps {
  planName: string;
  /** This month's spend, in micros with its currency. */
  charged?: MoneyLike | null;
  requestsThisMonth: number;
  trial: {
    hasTrialCredits: boolean;
    status: string;
    creditsRemaining: number;
    initialCredits: number;
    percentageRemaining: number;
    daysRemaining: number;
  };
}

export async function PlanSummary({
  planName,
  charged = null,
  requestsThisMonth,
  trial,
}: PlanSummaryProps) {
  const t = await getTranslations("dashboard");
  const format = await getFormatter();

  const showTrial = trial.hasTrialCredits && trial.status === "active";

  return (
    <div className="flex min-w-0 flex-wrap items-center justify-end gap-x-4 gap-y-1 text-xs text-muted-foreground">
      <span className="font-medium text-foreground">{planName}</span>
      <span>{t("plan.requests", { count: requestsThisMonth })}</span>
      {charged ? (
        <span className="font-medium text-foreground">
          {formatMoney(format, charged)}
        </span>
      ) : null}

      {showTrial ? (
        <span>
          {t("plan.trialRemaining", {
            remaining: format.number(trial.creditsRemaining, {
              notation: "compact",
              maximumFractionDigits: 1,
            }),
            initial: format.number(trial.initialCredits, {
              notation: "compact",
              maximumFractionDigits: 1,
            }),
          })}
          {" · "}
          {t("plan.trialDays", { days: trial.daysRemaining })}
        </span>
      ) : null}

      <span className="flex items-center gap-4">
        <Link href="/usage" className="transition-colors hover:text-foreground">
          {t("plan.viewUsage")}
        </Link>
        <Link
          href="/pricing"
          className="transition-colors hover:text-foreground"
        >
          {t("plan.viewPlans")}
        </Link>
      </span>
    </div>
  );
}

/**
 * Dashboard configuration — consumer-owned, imported by client
 * components (so, like `nav-config.ts`, it may hold React/Lucide
 * component values that must never cross the RSC boundary as props).
 *
 * The shipped defaults render a complete, honest AI-first home with no
 * editing: a hero from this item's own messages, a composer that opens
 * a new conversation, starter chips that fill it, a resume affordance
 * for unfinished work, and a quiet strip of recent conversations and
 * plan state at the foot. Every part is replaceable here rather than in
 * a component:
 *
 *  - `hero`: icon plus fully-qualified message keys for the title and
 *    subtitle. Point them at your product's namespace to say what this
 *    workspace is actually for.
 *  - `starters`: fully-qualified message keys (the `chatConfig.starters`
 *    contract). Each renders as a chip under the composer that opens a
 *    new conversation prefilled with that text. Empty hides the row.
 *  - `chatBasePath`: where the composer and the starters send the user.
 *    Defaults to the `chat` item's `/chat`; change it if your chat
 *    surface lives elsewhere, and note that the whole composer
 *    affordance only makes sense with a chat surface installed.
 *  - `showPlanSummary`: set false for a product that doesn't want
 *    billing state on its home page at all.
 *
 * There is no `shortcuts` seam: the links it held (artifacts, usage,
 * team) are all in the shell's navigation, and a second copy of the
 * same three links under the composer was the app's own menu rendered
 * twice.
 */

import { Sparkles, type LucideIcon } from "lucide-react";

export interface DashboardConfig {
  hero?: {
    icon?: LucideIcon;
    titleKey?: string;
    subtitleKey?: string;
  };
  /** Fully-qualified message keys, resolved namespace-less. */
  starters?: string[];
  chatBasePath?: string;
  showPlanSummary?: boolean;
}

export const dashboardConfig: DashboardConfig = {
  hero: {
    icon: Sparkles,
    titleKey: "dashboard.hero.title",
    subtitleKey: "dashboard.hero.subtitle",
  },
  starters: [
    "dashboard.starters.first",
    "dashboard.starters.second",
    "dashboard.starters.third",
  ],
  chatBasePath: "/chat",
  showPlanSummary: true,
};

import "server-only";

/**
 * Dashboard data seam — consumer-owned, read by the dashboard page on
 * the server.
 *
 * `getResume` answers "what was this person in the middle of?" The
 * default is the most recently updated conversation, which is right for
 * a generic AI workspace. A product whose work has real structure —
 * a multi-phase assessment, a wizard, a review queue — binds its own
 * notion of progress here and the hero's resume pill picks it up with
 * no component edit:
 *
 *   export async function getResume(actor: ResumeActor) {
 *     const run = await getActiveAssessment(actor.workspaceId, actor.userId);
 *     if (!run) return null;
 *     return {
 *       label: `Phase ${run.phase} of ${run.totalPhases}`,
 *       href: `/chat/${run.conversationId}`,
 *     };
 *   }
 *
 * Return `null` when there is nothing to resume — the pill is hidden
 * rather than rendered empty.
 */

import { listConversations } from "@intelligo-dev/core/conversations";

export interface ResumeActor {
  workspaceId: string;
  userId: string;
}

export interface ResumeTarget {
  /**
   * Plain text for the pill (already localized by whoever produced
   * it). Omit to let the dashboard use its own "continue" copy.
   */
  label?: string;
  /** Locale-less href; `@/i18n/navigation`'s Link localizes it. */
  href: string;
}

export async function getResume(
  actor: ResumeActor,
  options?: { chatBasePath?: string }
): Promise<ResumeTarget | null> {
  const [latest] = await listConversations(actor, { limit: 1 });
  if (!latest) return null;

  const base = options?.chatBasePath ?? "/chat";
  return {
    label: latest.title ?? undefined,
    href: `${base}/${latest.id}`,
  };
}
